export function chessFightTotalsV39(fight:ChessFightV39){const allies=new Set(fight.initialUnits.filter(unit=>unit.side==='ally').map(unit=>unit.uid)),enemies=new Set(fight.initialUnits.filter(unit=>unit.side==='enemy').map(unit=>unit.uid)),hp=new Map(fight.initialUnits.map(unit=>[unit.uid,unit.hp])),shields=new Map(fight.initialUnits.map(unit=>[unit.uid,unit.shield])),totals={damage:0,healing:0,shield:fight.initialUnits.filter(unit=>unit.side==='ally').reduce((sum,unit)=>sum+unit.shield,0)};for(const event of fight.events){const subject=event.target||event.actor,loss=Math.max(0,(hp.get(subject)??event.hp)-event.hp),shieldGain=Math.max(0,event.shield-(shields.get(subject)??event.shield));if(enemies.has(subject)&&['attack','skill','status'].includes(event.kind))totals.damage+=loss;hp.set(subject,event.hp);shields.set(subject,event.shield);if(allies.has(event.actor)){if(event.kind==='heal')totals.healing+=event.value;if(event.kind==='shield')totals.shield+=shieldGain;}}return totals;}
