export function chessEventLabelV39(event:ChessFightV39['events'][number]){const name=CHESS_EVENT_NAMES[event.action]||event.action;if(!event.value)return name;if(event.action==='mana-drain')return name+' · '+Math.abs(event.value);if(event.action==='intercept')return name+' · '+event.value+'%';if(event.action==='orbit')return name+' · '+event.value+'/3';if(event.action==='shield-break')return name+' · '+event.value+' de escudo';return event.kind==='status'&&['burn','silence','root','slow','intercept-ready','hunt-wound','displace-resist','pyre-zone'].includes(event.action)?name+' · '+(event.value/10).toLocaleString('pt-BR')+' s':name+' · '+event.value;}
